import re


def parse_duration(text):
    if not isinstance(text, str) or text == "":
        return None
    # Bare digits on their own represent seconds, e.g. "45" -> 45
    if re.fullmatch(r"[0-9]+", text):
        return int(text)
    # Unit string: optional h, m, s components in order, each number
    # must be followed by its unit letter (except the last bare-digit case above).
    m = re.fullmatch(
        r"(?P<hours>[0-9]+h)?(?P<minutes>[0-9]+m)?(?P<seconds>[0-9]+s)?", text
    )
    if not m:
        return None
    hours = int(m.group("hours")[:-1]) if m.group("hours") else 0
    minutes = int(m.group("minutes")[:-1]) if m.group("minutes") else 0
    seconds = int(m.group("seconds")[:-1]) if m.group("seconds") else 0
    return hours * 3600 + minutes * 60 + seconds
